mapper.select:
SELECT aa.`shop_no`, aa.`no`, aa.`name`, aa.`unit`, aa.`type`, aa.`brand`, aa.`bar_code`, bb.bill_type, bb.stock_no, bb.stock_name, AVG(bb.entry_price) AS `entry_price`, SUM(bb.total_qty) AS `total_qty`, bb.entry_unit, SUM(bb.entry_amount) AS `entry_amount`, SUM(bb.total_amount) AS `total_amount` FROM ( SELECT po.shop_no, po.bill_date, po.`bill_type`, pe.`stock_no`, pe.`stock_name`, pe.`entry_id`, pe.`entry_price`,pe.`total_qty`,pe.`entry_unit`,pe.`entry_amount`,pe.`total_amount`, pe.`create_time` FROM po_order po LEFT JOIN po_order_entry pe ON po.`bill_no`=pe.`bill_no` WHERE po.`audit_status`='YES' UNION ALL SELECT so.shop_no, so.bill_date, so.`bill_type`, se.`stock_no`, se.`stock_name`, se.`entry_id`, se.`entry_price`,se.`total_qty`,se.`entry_unit`,se.`entry_amount`,se.`total_amount`, se.`create_time` FROM se_order so LEFT JOIN se_order_entry se ON so.`bill_no`=se.`bill_no` WHERE so.`audit_status`='YES' UNION ALL SELECT wo.shop_no, wo.bill_date, wo.`bill_type`, we.`stock_no`, we.`stock_name`, we.`entry_id`, we.`entry_price`,we.`total_qty`,we.`entry_unit`,we.`entry_amount`,we.`entry_amount` AS `total_amount`,we.`create_time` FROM wh_order wo LEFT JOIN wh_order_entry we ON wo.`bill_no`=we.`bill_no` WHERE wo.`audit_status`='YES' ) bb LEFT JOIN data_product aa ON aa.`no`=bb.entry_id
and bb.bill_date <= #{param.toDate} and aa.status = #{param.status} and aa.type = #{param.type} and bb.stock_no = #{param.stock} and aa.no = #{param.productNo} and aa.shop_no in #{item}
and aa.type in #{item}
and bb.stock_no in #{item}
and aa.no in #{item}
and ( aa.no like '%${param.searchText}%' or aa.name like '%${param.searchText}%')
GROUP BY aa.no, bb.bill_type, bb.stock_no
